using System;
using Memoria;
using Memoria.Accessibility.AudioDescriptions;
using UnityEngine;
class Program
{
    static int passed,failed;
    static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
    static void Equal(string want,string got){Check(want==got,"Expected "+want+", got "+got);}
    static void Test(string name,Action run){try{PersistenSingleton<HonoInputManager>.Instance=new HonoInputManager();PersistenSingleton<UnityXInput.XInputManager>.Instance=new UnityXInput.XInputManager();UnityEngine.Input.Down.Clear();HonoInputManager.Active=true;Configuration.Accessibility.ControllerNaming="PlayStation";UICamera.currentScheme=UICamera.ControlScheme.Mouse;EventInput.isJapaneseLayout=false;run();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+e.Message);}}
    static XInputDotNetPure.GamePadState Pad(ushort buttons=0,short x=0,byte trigger=0){var raw=new XInputDotNetPure.GamePadState.RawState();raw.Gamepad.wButtons=buttons;raw.Gamepad.sThumbLX=x;raw.Gamepad.bLeftTrigger=trigger;return new XInputDotNetPure.GamePadState(true,raw,XInputDotNetPure.GamePadDeadZone.Circular);}
    static string Read(Control control,bool configured=true,string tag="",bool timed=true){return NativePromptInputNames.Read(control,configured,tag,timed);}
    static int Main(string[] args)
    {
        if(args.Length==2 && args[0]=="--verify"){FF9Access.Tests.NativeReaderVerification.VerifyTimedPrompts(args[1]);return 0;}
        Test("controller uses shape names instead of keyboard B C D",()=>{var i=PersistenSingleton<HonoInputManager>.Instance;i.AccessibilityInputDevice=PromptInputDevice.Controller;Equal("Cross",Read(Control.Confirm));Equal("Circle",Read(Control.Cancel));Equal("Triangle",Read(Control.Menu));Equal("Square",Read(Control.Special));});
        Test("plugged controller does not override active keyboard",()=>{var i=PersistenSingleton<HonoInputManager>.Instance;i.AccessibilityInputDevice=PromptInputDevice.Keyboard;i.IsControllerConnect=true;Equal("Bravo",Read(Control.Menu));Equal("Delta",Read(Control.Special));});
        Test("current keyboard remapping is spoken",()=>{var i=PersistenSingleton<HonoInputManager>.Instance;i.AccessibilityInputDevice=PromptInputDevice.Keyboard;i.InputKeysPrimary[(int)Control.Menu]=KeyCode.F;Equal("Foxtrot",Read(Control.Menu));i.InputKeysPrimary[(int)Control.Menu]=KeyCode.Return;Equal("Enter",Read(Control.Menu));});
        Test("current controller remapping is spoken",()=>{var i=PersistenSingleton<HonoInputManager>.Instance;i.AccessibilityInputDevice=PromptInputDevice.Controller;i.JoystickKeysPrimary[(int)Control.Confirm]="JoystickButton3";Equal("Triangle",Read(Control.Confirm));});
        Test("fixed button glyph honors physical-to-logical keyboard mapping",()=>{var i=PersistenSingleton<HonoInputManager>.Instance;i.AccessibilityInputDevice=PromptInputDevice.Keyboard;i.FixedControlResult=Control.Special;Equal("Delta",Read(Control.Confirm,false));Check(i.RemappedPhysicalCalls==1,"fixed glyph skipped native physical mapping");});
        Test("fixed controller glyph uses native defaults and Japanese swap",()=>{var i=PersistenSingleton<HonoInputManager>.Instance;i.AccessibilityInputDevice=PromptInputDevice.Controller;EventInput.isJapaneseLayout=true;i.DefaultJoystickInputKeys[0]="JoystickButton1";i.DefaultJoystickInputKeys[1]="JoystickButton0";Equal("Cross",Read(Control.Confirm,false));});
        Test("forced keyboard/controller glyph tags retain their native meaning",()=>{var i=PersistenSingleton<HonoInputManager>.Instance;i.AccessibilityInputDevice=PromptInputDevice.Keyboard;Equal("Triangle",Read(Control.Menu,true,NGUIText.JoyStickButtonIcon));i.AccessibilityInputDevice=PromptInputDevice.Controller;Equal("Bravo",Read(Control.Menu,true,NGUIText.KeyboardButtonIcon));});
        Test("existing Xbox and Generic naming preferences apply",()=>{PersistenSingleton<HonoInputManager>.Instance.AccessibilityInputDevice=PromptInputDevice.Controller;Configuration.Accessibility.ControllerNaming="Xbox";Equal("Y",Read(Control.Menu));Configuration.Accessibility.ControllerNaming="Generic";Equal("top face button",Read(Control.Menu));});
        Test("non-timed keyboard labels remain ordinary key names",()=>{PersistenSingleton<HonoInputManager>.Instance.AccessibilityInputDevice=PromptInputDevice.Keyboard;Equal("B",Read(Control.Menu,true,"",false));Equal("Up",Read(Control.Up));});
        Test("input mode survives idle and changes on actual presses",()=>{var t=new PromptInputDeviceTracker();t.Observe(false,true,true);Check(t.Device==PromptInputDevice.Controller,"controller press not retained");t.Observe(false,false,true);Check(t.Device==PromptInputDevice.Controller,"idle forgot source");t.Observe(true,false,true);Check(t.Device==PromptInputDevice.Keyboard,"keyboard did not take over");});
        Test("background input does not change mode; simultaneous input follows native keyboard priority",()=>{var t=new PromptInputDeviceTracker();t.Observe(false,true,true);t.Observe(true,false,false);Check(t.Device==PromptInputDevice.Controller,"background input changed source");t.Observe(true,true,true);Check(t.Device==PromptInputDevice.Keyboard,"simultaneous priority wrong");});
        Test("first native sword-fight phase is active before mobile HUD update",()=>{Check(NativeTimedInputContext.Active,"native phase3 not protected");foreach(int entrance in new[]{327,315,316})Check(!TimedPromptPhase.IsChanbara(64,1,entrance,3),"unrelated entrance protected");Check(!TimedPromptPhase.IsChanbara(64,1,5,4) && !TimedPromptPhase.IsChanbara(63,1,5,3) && !TimedPromptPhase.IsChanbara(64,2,5,3),"outside phase was suppressed");});
        Test("menus cannot activate stale field timed state",()=>{UIManager.Instance.State=UIManager.UIState.Title;Check(!NativeTimedInputContext.Active,"stale title activated native field");UIManager.Instance.State=UIManager.UIState.FieldHUD;});
        Test("unavailable native field state cannot throw from animation hooks",()=>{var e=PersistenSingleton<EventEngine>.Instance;e.eBin.ThrowOnRead=true;try{Check(!NativeTimedInputContext.Active,"unavailable state was accepted");}finally{e.eBin.ThrowOnRead=false;}});
        Test("punctuation binding has a spoken key name",()=>{var i=PersistenSingleton<HonoInputManager>.Instance;i.AccessibilityInputDevice=PromptInputDevice.Keyboard;i.InputKeysPrimary[(int)Control.Special]=KeyCode.Semicolon;Assets.Sources.Scripts.UI.Common.FF9UIDataTool.KeyboardIconLabel[KeyCode.Semicolon]=";";Equal("Semicolon",Read(Control.Special));});
        Test("verified one-button timed template leads with the action",()=>{Equal("Cross",PromptButtonNames.FormatDialogButtons("Press   !",new[]{"Cross"},true));Equal("Bravo",PromptButtonNames.FormatDialogButtons("Press !",new[]{"Bravo"},true));Equal("To follow Blank, choose:",PromptButtonNames.FormatDialogButtons("To follow Blank, choose:",new string[0],true).Trim());Check(PromptButtonNames.FormatDialogButtons("Instructions",new[]{"Up","Cross"},true).Contains("Instructions"),"instructions were shortened");Equal("Press ! Cross",PromptButtonNames.FormatDialogButtons("Press !",new[]{"Cross"},false));});
        Test("Windows gameplay pad edge is observed when raw Unity reports none",()=>{var x=PersistenSingleton<UnityXInput.XInputManager>.Instance;x.PreviousState=Pad();x.CurrentState=Pad(0x1000);Check(UnityXInput.Input.GetButtonDown("JoystickButton0") && !UnityEngine.Input.GetButtonDown("JoystickButton0"),"fixture backend mismatch");var t=new PromptInputDeviceTracker();NativePromptInputSource.Observe(new SourceControl[16],t,PersistenSingleton<HonoInputManager>.Instance,false);Check(t.Device==PromptInputDevice.Controller,"gameplay controller was missed");});
        Test("native movement remap and secondary keyboard bindings switch back",()=>{var t=new PromptInputDeviceTracker();t.Observe(false,true,true);UnityEngine.Input.Down.Add(HonoInputManager.MemoriaKeyBindings[0]);NativePromptInputSource.Observe(new SourceControl[16],t,PersistenSingleton<HonoInputManager>.Instance,false);Check(t.Device==PromptInputDevice.Keyboard,"movement binding was missed");UnityEngine.Input.Down.Clear();t.Observe(false,true,true);UnityEngine.Input.Down.Add(KeyCode.Return);NativePromptInputSource.Observe(new SourceControl[16],t,PersistenSingleton<HonoInputManager>.Instance,true);Check(t.Device==PromptInputDevice.Keyboard,"secondary native key was missed");});
        Test("deadzoned native axes triggers and D-pad edges retain idle mode",()=>{var x=PersistenSingleton<UnityXInput.XInputManager>.Instance;var t=new PromptInputDeviceTracker();x.PreviousState=Pad();x.CurrentState=Pad(0,26000);NativePromptInputSource.Observe(new SourceControl[16],t,PersistenSingleton<HonoInputManager>.Instance,false);Check(t.Device==PromptInputDevice.Controller,"native stick edge missed");t.Observe(true,false,true);x.PreviousState=x.CurrentState;NativePromptInputSource.Observe(new SourceControl[16],t,PersistenSingleton<HonoInputManager>.Instance,false);Check(t.Device==PromptInputDevice.Keyboard,"held stick overrode newer keyboard input");x.CurrentState=Pad(1);NativePromptInputSource.Observe(new SourceControl[16],t,PersistenSingleton<HonoInputManager>.Instance,false);Check(t.Device==PromptInputDevice.Controller,"native D-pad edge missed");t.Observe(true,false,true);x.PreviousState=Pad();x.CurrentState=Pad(0,0,200);NativePromptInputSource.Observe(new SourceControl[16],t,PersistenSingleton<HonoInputManager>.Instance,false);Check(t.Device==PromptInputDevice.Controller,"native trigger edge missed");});
        Console.WriteLine("PromptInputIntegration: "+passed+" passed, "+failed+" failed");return failed==0?0:1;
    }
}
